.comparison130{--cmp-accent:#b4df65;--cmp-tint:#eff5e9;--cmp-bg:#055c4d;box-sizing:border-box;position:relative;z-index:4;width:100%;padding:64px 30px 76px;background:var(--cmp-bg);color:#fff;border-radius:30px 30px 0 0;font-family:Inter,sans-serif}
.comparison130 *{box-sizing:border-box}
.comparison130__inner{width:100%;max-width:1100px;margin:auto}
.comparison130__heading{max-width:950px;margin:0 auto 62px;text-align:center}
.comparison130 .comparison130__heading h2{font:800 52px/1.14 Oswald,sans-serif;letter-spacing:-.025em;color:#fff;margin:0;text-wrap:balance}
.comparison130 .comparison130__heading h2 span{color:inherit;background:none;padding:0;box-shadow:none;border-radius:0}
.comparison130 .comparison130__heading p{font-size:18px;line-height:1.65;max-width:800px;margin:18px auto 0;color:#fff}
.comparison130__card{border:1px solid #202820;border-radius:20px;overflow:visible;background:#fffefa;box-shadow:4px 5px 0 #112d2c66}
.comparison130__table{width:100%;table-layout:fixed;border:0;border-collapse:separate;border-spacing:0;color:#1a1a1f;background:transparent;font-size:16px;line-height:1.45}
.comparison130 .comparison130__table th,.comparison130 .comparison130__table td{padding:18px 16px;border:0;border-bottom:1px solid #19261c18;vertical-align:middle;text-align:center;overflow-wrap:anywhere;font:inherit;color:inherit}
.comparison130 .comparison130__table thead th{background:#f0f1ed;vertical-align:top;padding-top:0;padding-bottom:18px;border-bottom:1px solid #202820}
.comparison130 .comparison130__table thead th:has(.comparison130__feature-label){vertical-align:bottom}
.comparison130 .comparison130__table thead th:first-child{border-top-left-radius:19px}
.comparison130 .comparison130__table thead th:last-child{border-top-right-radius:19px}
.comparison130 .comparison130__table tbody tr:last-child>:first-child{border-bottom-left-radius:19px}
.comparison130 .comparison130__table tbody tr:last-child>:last-child{border-bottom-right-radius:19px}
.comparison130 .comparison130__table .comparison130__ours{background:var(--cmp-tint)}
.comparison130 .comparison130__table thead .comparison130__ours{background:var(--cmp-accent)}
.comparison130 .comparison130__table tbody th{text-align:left;font-weight:500}
.comparison130 .comparison130__table tbody tr:nth-child(even)>:not(.comparison130__ours){background:#f0f1ed}
.comparison130 .comparison130__table tr:last-child>*{border-bottom:0}
.comparison130__feature{width:34%}
.comparison130 .comparison130__label{display:block;font:700 22px/1.2 Oswald,sans-serif;text-wrap:balance;text-align:center}
.comparison130 .comparison130__feature-label{font-size:25px;text-align:left}
.comparison130__objects{position:relative;z-index:1;height:94px;display:flex;align-items:center;justify-content:center;gap:4px;width:100%;margin:-28px 0 10px;min-width:0}
.comparison130 .comparison130__objects img{display:block;min-width:0;max-width:100%;width:auto;height:100%;max-height:94px;object-fit:contain;flex:0 1 auto;filter:drop-shadow(0 5px 3px #13271a25);transform:none}
.comparison130 .comparison130__objects img[data-comparison-object="coffee"],.comparison130 .comparison130__objects img[data-comparison-object="can"]{height:78px}
.comparison130 .comparison130__objects[data-count="2"] img{max-width:47%}
.comparison130 .comparison130__objects svg{width:52px;height:64px;fill:#e5c5a5;stroke:#2c332c;stroke-width:1.5}
.comparison130__status{display:inline-grid;place-items:center;flex:none;width:30px;height:30px;border-radius:50%;color:#fff;font:500 22px/1 Inter,sans-serif;box-shadow:0 2px 0 #19261c30}
.comparison130__status--yes{background:#4b702e}
.comparison130__status--no{background:#ad493c}
.comparison130 .comparison130__table--paired th{width:50%}
.comparison130 .comparison130__table--paired td{vertical-align:top;text-align:left}
.comparison130__pair{display:flex;align-items:flex-start;gap:12px}
.comparison130__pair>span:last-child{padding-top:3px;min-width:0}
.comparison130__sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
.comparison130--diagram .comparison130__objects{height:90px;margin:24px auto 0}
.comparison130--diagram .breathing-diagram63{background:#fffefa;border-radius:20px;padding:24px;color:#1a1a1f}
@media(max-width:767px){
 .comparison130{padding:40px 15px 48px;border-radius:24px 24px 0 0}
 .comparison130__heading{margin-bottom:48px}
 .comparison130 .comparison130__heading h2{font-size:36px}
 .comparison130 .comparison130__heading p{font-size:16px;margin-top:14px}
 .comparison130__card{border-radius:15px;box-shadow:3px 4px 0 #112d2c66}
 .comparison130 .comparison130__table{font-size:13px;line-height:1.45}
 .comparison130 .comparison130__table th,.comparison130 .comparison130__table td{padding:13px 7px}
 .comparison130 .comparison130__table thead th{padding:0 5px 13px}
 .comparison130 .comparison130__table thead th:first-child{border-top-left-radius:14px}
 .comparison130 .comparison130__table thead th:last-child{border-top-right-radius:14px}
 .comparison130 .comparison130__table tbody tr:last-child>:first-child{border-bottom-left-radius:14px}
 .comparison130 .comparison130__table tbody tr:last-child>:last-child{border-bottom-right-radius:14px}
 .comparison130 .comparison130__label{font-size:16px}
 .comparison130 .comparison130__feature-label{font-size:18px}
 .comparison130__feature{width:34%}
 .comparison130__objects{height:64px;gap:2px;margin-top:-20px;margin-bottom:8px}
 .comparison130 .comparison130__objects img{max-height:64px}
 .comparison130 .comparison130__objects img[data-comparison-object="coffee"],.comparison130 .comparison130__objects img[data-comparison-object="can"]{height:52px}
 .comparison130 .comparison130__objects svg{max-width:42%;height:44px}
 .comparison130__status{width:25px;height:25px;font-size:19px}
 .comparison130__pair{gap:8px}
 .comparison130__pair>span:last-child{padding-top:1px}
}
@media(max-width:359px){.comparison130 .comparison130__table{font-size:12px}.comparison130 .comparison130__label{font-size:15px}.comparison130 .comparison130__feature-label{font-size:16px}.comparison130 .comparison130__table th,.comparison130 .comparison130__table td{padding-inline:5px}}
.ark-large-text64 .comparison130 .comparison130__table{font-size:18px}
.ark-large-text64 .comparison130 .comparison130__label{font-size:22px}
